// ── Derived lookups ─────────────────────────────────────────────────────
// Hand-authored; the generator never rewrites below this line.

/** Every prefix the source document declares, for O(1) membership. @internal */
export const FOREIGN_PREFIX_SET: ReadonlySet<string> = new Set(FOREIGN_PREFIXES);

/** Type name → type index. @internal */
export const TYPE_INDEX: ReadonlyMap<string, number> = new Map(TYPE_NAMES.map((name, index) => [name, index]));

/** Property name → property index. @internal */
export const PROPERTY_INDEX: ReadonlyMap<string, number> = new Map(PROPERTY_NAMES.map((name, index) => [name, index]));

/** Decode one comma-joined index row. An empty row is an empty list, not a `[NaN]`. @internal */
export function decodeRow(row: string | undefined): readonly number[] {
	if (row === undefined || row === "") return [];
	const out: number[] = [];
	for (const part of row.split(",")) out.push(Number(part));
	return out;
}

/** Decode a superseded-pair table into `index → supersedingIndex`. @internal */
function decodePairs(rows: readonly string[]): ReadonlyMap<number, number> {
	const map = new Map<number, number>();
	for (const row of rows) {
		const [from, to] = decodeRow(row);
		if (from !== undefined && to !== undefined) map.set(from, to);
	}
	return map;
}

/** Deprecated class index → the class index that supersedes it. @internal */
export const SUPERSEDED_TYPE_MAP: ReadonlyMap<number, number> = decodePairs(SUPERSEDED_TYPES);

/** Deprecated property index → the property index that supersedes it. @internal */
export const SUPERSEDED_PROPERTY_MAP: ReadonlyMap<number, number> = decodePairs(SUPERSEDED_PROPERTIES);
